export const WORKSPACE_EXTERNAL_WRITE_PROVENANCE = {
  TRUSTED_SYSTEM: "trusted-system",
  DIRECT_OPERATOR: "direct-operator",
  EXTERNAL: "external",
  DERIVED: "derived",
  INVALID: "invalid",
  MISSING: "missing",
} as const;

export type WorkspaceExternalWriteProvenance =
  (typeof WORKSPACE_EXTERNAL_WRITE_PROVENANCE)[keyof typeof WORKSPACE_EXTERNAL_WRITE_PROVENANCE];

export type WorkspaceExternalWriteProvenanceInput =
  | WorkspaceExternalWriteProvenance
  | "trusted"
  | "operator"
  | "trusted_system"
  | "direct_operator"
  | "system"
  | null
  | undefined
  | { readonly provenance?: unknown; readonly source?: unknown; readonly kind?: unknown };

export type WorkspaceExternalWriteDecision =
  | { readonly allowed: true; readonly provenance: "trusted-system" | "direct-operator" }
  | { readonly allowed: false; readonly provenance: WorkspaceExternalWriteProvenance; readonly reason: string };

export class WorkspaceExternalWriteProvenanceError extends Error {
  readonly code = "WORKSPACE_EXTERNAL_WRITE_PROVENANCE_DENIED";
  readonly provenance: WorkspaceExternalWriteProvenance;

  constructor(provenance: WorkspaceExternalWriteProvenance, message?: string) {
    super(message ?? `workspace-external write denied for provenance ${provenance}`);
    this.name = "WorkspaceExternalWriteProvenanceError";
    this.provenance = provenance;
  }
}

function readProvenanceValue(input: WorkspaceExternalWriteProvenanceInput): unknown {
  if (input !== null && typeof input === "object") {
    if ("provenance" in input) return input.provenance;
    if ("source" in input) return input.source;
    if ("kind" in input) return input.kind;
  }
  return input;
}

/**
 * Normalize provenance without granting trust to unknown values. This is the sole
 * provenance boundary used by write, edit, and apply_patch.
 */
export function normalizeWorkspaceExternalWriteProvenance(
  input: WorkspaceExternalWriteProvenanceInput,
): WorkspaceExternalWriteProvenance {
  const value = readProvenanceValue(input);

  if (value === WORKSPACE_EXTERNAL_WRITE_PROVENANCE.TRUSTED_SYSTEM || value === "trusted" || value === "trusted_system" || value === "system") {
    return WORKSPACE_EXTERNAL_WRITE_PROVENANCE.TRUSTED_SYSTEM;
  }
  if (
    value === WORKSPACE_EXTERNAL_WRITE_PROVENANCE.DIRECT_OPERATOR ||
    value === "operator" ||
    value === "direct_operator"
  ) {
    return WORKSPACE_EXTERNAL_WRITE_PROVENANCE.DIRECT_OPERATOR;
  }
  if (value === WORKSPACE_EXTERNAL_WRITE_PROVENANCE.EXTERNAL) {
    return WORKSPACE_EXTERNAL_WRITE_PROVENANCE.EXTERNAL;
  }
  if (value === WORKSPACE_EXTERNAL_WRITE_PROVENANCE.DERIVED) {
    return WORKSPACE_EXTERNAL_WRITE_PROVENANCE.DERIVED;
  }
  if (value === WORKSPACE_EXTERNAL_WRITE_PROVENANCE.INVALID) {
    return WORKSPACE_EXTERNAL_WRITE_PROVENANCE.INVALID;
  }
  return WORKSPACE_EXTERNAL_WRITE_PROVENANCE.MISSING;
}

export function isTrustedWorkspaceExternalWriteProvenance(
  input: WorkspaceExternalWriteProvenanceInput,
): boolean {
  const provenance = normalizeWorkspaceExternalWriteProvenance(input);
  return (
    provenance === WORKSPACE_EXTERNAL_WRITE_PROVENANCE.TRUSTED_SYSTEM ||
    provenance === WORKSPACE_EXTERNAL_WRITE_PROVENANCE.DIRECT_OPERATOR
  );
}

export function decideWorkspaceExternalWriteProvenance(
  input: WorkspaceExternalWriteProvenanceInput,
): WorkspaceExternalWriteDecision {
  const provenance = normalizeWorkspaceExternalWriteProvenance(input);
  if (isTrustedWorkspaceExternalWriteProvenance(provenance)) {
    return {
      allowed: true,
      provenance:
        provenance === WORKSPACE_EXTERNAL_WRITE_PROVENANCE.TRUSTED_SYSTEM
          ? WORKSPACE_EXTERNAL_WRITE_PROVENANCE.TRUSTED_SYSTEM
          : WORKSPACE_EXTERNAL_WRITE_PROVENANCE.DIRECT_OPERATOR,
    };
  }

  return {
    allowed: false,
    provenance,
    reason: `workspace-external write requires trusted-system or direct-operator provenance; received ${provenance}`,
  };
}

export function assertWorkspaceExternalWriteProvenance(
  input: WorkspaceExternalWriteProvenanceInput,
): WorkspaceExternalWriteDecision["allowed"] extends true ? "trusted-system" | "direct-operator" : never {
  const decision = decideWorkspaceExternalWriteProvenance(input);
  if (!decision.allowed) {
    throw new WorkspaceExternalWriteProvenanceError(decision.provenance, decision.reason);
  }
  return decision.provenance;
}

/**
 * Compatibility-shaped helper for callers that use an assertion-style API.
 * Provenance is checked before any path resolution or filesystem mutation.
 */
export function assertWorkspaceExternalWriteAllowed(
  input: WorkspaceExternalWriteProvenanceInput,
): void {
  assertWorkspaceExternalWriteProvenance(input);
}

export const isWorkspaceExternalWriteProvenanceAllowed = isTrustedWorkspaceExternalWriteProvenance;

export default WORKSPACE_EXTERNAL_WRITE_PROVENANCE;

